"""Focused website value proof; it never adds a PAIA product surface or AI service."""
from html import escape
import json
from story import inputs, title, sections, current_task
from prompt_preview import narrow_board


def render(t, a, button, icon):
    def ctl(label, attr='', cls='pc-control'):
        return f'<button type="button" class="{cls}" {attr} disabled>{label}</button>'
    data = inputs(t)
    headings = sections(t)
    def entry(row):
        return f'''<article class="fs-expression" data-proof-expression="{row['id']}"><time>2026 · {row['date']}</time><p>{escape(row['text'])}</p><div class="vp-expression-actions"><details class="fs-source"><summary>{t('核对来源','Check source')}</summary><p>ChatGPT · {row['source']} · {row['time']}</p><p>{t('原始用户输入 · 虚构示例','Original user input · Fictional example')}</p></details><a class="vp-reuse-link" href="#prompt-reuse" data-story-reuse="{row['id']}" aria-label="{t('核对并复用这条输入','Inspect and reuse this input')} — {row['date']}">{t('复用这句','Use this wording')} <span aria-hidden="true">↗</span></a></div></article>'''

    lead = f'''<section class="vp-lead wrap" id="input-library" aria-labelledby="vp-lead-title"><div><p class="eyebrow">{t('不是所有旧话都重要。下面两条，就会改变这次任务。','NOT EVERY OLD INPUT MATTERS. THESE ONES CHANGE THE REQUEST.')}</p><h2 id="vp-lead-title">{t('新任务开始了，<br>已经想清楚的别丢。','A new task.<br>Keep what you worked out.')}</h2></div><p>{t('你准备把自己的学习观察写成文章。只说“帮我列提纲”，还没有说清真正的论点，也没带上你已经确认的证据边界。','You’re turning learning observations into an article. “Help me write an outline” doesn’t yet carry the question you chose—or the limits you put on your claims.')}</p></section>'''
    proof_items = [
        ('a', t('真正要讨论的论点','The question worth writing about'), t('还没带入：不是读更多，而是能否独立解释。','Not included yet: explaining an idea, not reading more.'), t('已带入原话：讨论能否用自己的话解释。','Exact wording included: ask whether I can explain it myself.')),
        ('c', t('不能丢失的证据边界','The limit on the claim'), t('还没带入：两周个人尝试，不能推广给所有人。','Not included yet: a two-week experiment is not universal evidence.'), t('已带入原话：只写个人经历，不推成普遍结论。','Exact wording included: personal experience, not a universal claim.')),
    ]
    proof_json = [dict(id=k, text=next(x['text'] for x in data if x['id']==k), missing=missing, included=done) for k,_,missing,done in proof_items]
    proof_status = ''.join(f'<div class="vp-proof-line" data-proof-line="{key}" data-state="missing"><span class="vp-proof-indicator" aria-hidden="true">—</span><div><h4>{label}</h4><p data-proof-wording>{missing}</p></div></div>' for key,label,missing,done in proof_items)
    workbench = f'''<section class="vp-workbench wrap" id="thought-library" data-value-proof data-proof-view="reading" data-locale="{t('zh','en')}" aria-label="{t('用自己的原话，把新请求说完整','Make the new request specific with your own wording')}">
<div class="vp-guide-bar"><p><span class="vp-sample-dot" aria-hidden="true"></span>{t('虚构输入 · 页面内演示 · 不调用 AI','FICTIONAL INPUTS · PAGE-LOCAL DEMO · NO AI CALLS')}</p><span>{t('先选一条原话，核对后填入','Choose a passage. Inspect it. Insert it.')}</span></div>
<nav class="vp-mobile-navigation" aria-label="{t('网站演示位置，不是产品导航','Website demo views, not product navigation')}" hidden><button type="button" data-proof-view-pick="reading" aria-pressed="true">{t('看过去的表达','Past wording')}</button><button type="button" data-proof-view-pick="draft" aria-pressed="false">{t('看当前请求','Current request')} <span data-proof-draft-indicator aria-hidden="true"></span></button></nav>
<div class="vp-workbench-grid"><div class="vp-reading-column" data-proof-pane="reading"><div class="fs-topic-window"><header><span>{icon('topic','mini-icon')}{t('思想库','Thought Library')}</span><span>{t('已打开的个人主题','SELECTED PERSONAL TOPIC')}</span></header><div class="fs-topic-paper"><p class="fs-topic-back">{t('我的主题','MY TOPICS')}</p><h3>{title(t)}</h3><p class="vp-reader-note">{t('两次对话里的原话，放进自己建立的章节。','Your words from two conversations, in sections you created.')}</p><section><h4>{headings[0]}</h4>{entry(data[0])}{entry(data[1])}</section><section><h4>{headings[1]}</h4>{entry(data[2])}{entry(data[3])}</section><p class="vp-reader-end">{t('示例主题到此结束 · 没有 AI 生成的观点','End of example topic · No AI-generated opinions')}</p></div></div><div class="vp-reading-foot"><p>{t('原话保留来源。工作文字可修改。章节和顺序由你决定。','Originals keep their sources. Working text can change. You choose the sections and their order.')}</p>{a('demo.html', t('试试编辑与来源核对','Try edits and source readback'),'text-link','#input-library')}</div></div>
<div class="vp-current-column" data-proof-pane="draft" id="prompt-reuse"><div class="vp-current-heading"><div><span>{t('今天 · 准备一个新请求','TODAY · A NEW REQUEST')}</span><h3>{t('把这次请求说具体。','Make this request specific.')}</h3></div></div>{narrow_board(t,ctl)}<div class="vp-task-proof" aria-live="polite" aria-atomic="false"><div class="vp-proof-heading"><h3>{t('这次明确带回了什么','What this request now includes')}</h3><span>{t('演示提示','DEMO GUIDE')}</span><button type="button" class="pc-quiet" data-proof-reset disabled>{t('还原请求','Reset request')}</button></div>{proof_status}<p class="vp-proof-disclaimer">{t('只核对两条示例原话是否完整出现在输入框，不评价自由输入，不是 AI 分析。','Checks only whether two exact sample passages are in the draft. It does not evaluate your writing or run AI analysis.')}</p></div><p class="vp-board-availability">{t('窄浮板为已批准、待实施的 v4 设计。普通手动复用不依赖 Pro；真实 AI 推荐尚未开放。','The narrow board is the approved, not-yet-implemented v4 design. Manual reuse does not require Pro. Real AI recommendations are not available.')}</p></div></div>
<div data-proof-fixture hidden>{escape(json.dumps(proof_json,ensure_ascii=False))}</div><div class="vp-proof-footer"><p>{t('改变的不是“多了一段文字”，而是请求重新带上了你此前确定的论点与边界。','The difference is not more text. Your request carries the question and limits you had already worked out.')}</p>{a('demo.html',t('继续完整交互演示','Open the complete interactive demo'),'text-link')}</div></section>'''

    continuity = f'''<section class="vp-continuity wrap" aria-labelledby="vp-continuity-title"><div><p class="eyebrow">{t('为什么值得持续留下来','WHY KEEP IT OVER TIME')}</p><h2 id="vp-continuity-title">{t('不是存得更多，<br>是下次找得回、用得准。','Not more to store.<br>More to build on.')}</h2></div><div><p>{t('长期写作会留下论点，学习会留下自己的解释，反复决策会留下不想再讨论一遍的条件。PAIA 让这些用户输入有来源、有工作版本，也有你自己的组织方式。','Writing leaves you with arguments. Learning leaves you with explanations. Decisions leave you with conditions you don’t want to rethink. PAIA gives those inputs a source, a working version and your own structure.')}</p><p class="fs-secondary">{t('有价值的内容需要你继续判断和维护。它不保证记录越多越有用，也不会把过去说过的话自动当成现在的立场。','Useful material still needs your judgment and maintenance. More records do not guarantee more value, and past wording is not automatically your position today.')}</p>{a('use-cases.html',t('看写作、学习和长期计划的不同用法','Explore writing, learning and long-term plans'),'text-link')}</div></section>'''
    privacy = f'''<section class="fs-privacy wrap" id="personal-context" aria-labelledby="fs-privacy-title"><div><p class="eyebrow">{t('AI CONTEXT / 下一层使用，由你决定','AI CONTEXT / THE NEXT LAYER IS YOUR CHOICE')}</p><h2 id="fs-privacy-title">{t('保存下来，<br>不等于允许 AI 读取。','Saved for you.<br>Not automatically shared.')}</h2><div class="vp-permission-preview" aria-label="{t('访问默认关闭的静态示意','Static illustration of default-off access')}"><span>{t('AI 访问：关','AI access: off')}</span><span>{t('我的信息','My Information')}</span><span>{t('我的规则','My Rules')}</span><span>{t('我的现在','My Now')}</span><span>{t('我的输入','My Inputs')}</span></div></div><div><p>{t('四张卡片分别管理背景、回应规则、当前情况和允许读取的主题。全局、卡片与新主题默认关闭；连接可用后，获准的 AI 才能在你选择的范围内读取。','Four cards separate background, response rules, current circumstances and topics open for reading. Global access, cards and new topics start off. When real connections become available, authorized AI can read within your choices.')}</p><p class="fs-secondary">{t('本地保存、找回、编辑和手动复用，不必等待 AI 服务。真实外部连接、Pro 推荐和云同步尚未开放。','Local capture, retrieval, editing and manual reuse do not need an AI service. Real external connections, Pro recommendations and cloud sync are not available yet.')}</p>{a('demo.html',t('试着只开放一个主题','Try allowing just one topic'),'text-link','#personal-context')}{a('principles.html',t('了解数据与权限','Understand data and permissions'),'text-link')}</div></section>'''
    fair = f'''<section class="vp-native wrap" aria-labelledby="vp-native-title"><div><p class="eyebrow">{t('与你已有的工具一起判断','CONSIDER IT ALONGSIDE WHAT YOU ALREADY USE')}</p><h2 id="vp-native-title">{t('ChatGPT 已经很有用。<br>PAIA 多做的是哪一层？','ChatGPT already does a lot.<br>Where does PAIA fit?')}</h2></div><div class="vp-native-columns"><div><h3>{t('原生功能已经能做的事','What native features already do')}</h3><p>{t('搜索能找回历史聊天；Project 可以集中聊天、文件和指令；Memory 能利用相关过往信息。只要这些已经够用，就不必为了多一个工具安装 PAIA。','Search finds past chats. Projects bring chats, files and instructions together. Memory can use relevant past information. When those meet your needs, another tool is unnecessary.')}</p><p class="vp-native-sources"><a href="https://help.openai.com/en/articles/10056348-finding-your-chats-projects-and-files-in-chatgpt" rel="noreferrer">Search</a> · <a href="https://help.openai.com/en/articles/10169521-projects-in-chatgpt" rel="noreferrer">Projects</a> · <a href="https://help.openai.com/en/articles/8590148-memory-in-chatgpt" rel="noreferrer">Memory</a><span>{t('OpenAI 官方说明','Official OpenAI documentation')}</span></p></div><div><h3>{t('PAIA 专注于你的输入本身','PAIA focuses on your inputs themselves')}</h3><p>{t('逐条核对自己说过什么，分开保留原始来源与工作修改，跨会话按个人主题阅读，再主动复用准确的措辞。它不是替代 ChatGPT 和记忆，而是让你能直接管理和使用这份自己的材料。','Inspect what you said, keep source and working edits separate, read it across conversations in personal topics, and deliberately reuse exact wording. It does not replace ChatGPT or memory; it lets you work directly with your own material.')}</p><p class="fs-secondary">{t('笔记和模板工具也能保存与复用文字。PAIA 的区别在于从经授权保存的 AI 输入出发，连起这条工作路径；是否值得安装，取决于你是否经常需要它。','Notes and template tools can also save and reuse text. PAIA connects that workflow starting with authorized AI inputs. Whether it earns a place depends on how often you need that path.')}</p></div></div></section>'''
    close = f'''<section class="core-close" data-close-brand><div class="core-close-inner wrap"><div><p class="eyebrow">{t('先试一遍，再决定是否需要','TRY THE WORKFLOW. THEN DECIDE.')}</p><h2>{t('让下一次任务，<br>接上你自己的积累。','Start the next task<br>with your own thinking.')}</h2><p>{t('完整演示使用虚构数据，无需安装或邮箱。测试版面向桌面 Chrome 和 ChatGPT 网页版，申请后按当前范围邀请。','The complete demo uses fictional data, without an install or email. The extension is an invite-only test for desktop Chrome and ChatGPT Web.')}</p><div class="actions">{button('demo.html',t('试用交互演示','Try the interactive demo'))}{a('beta.html',t('申请内测','Request beta access'),'text-link')}</div>{a('status.html',t('先了解当前可用范围','Check current availability'),'fs-close-scope text-link')}</div><div class="core-close-mark"><img src="/assets/website/brand/paia-logo-v1.webp" width="480" height="480" alt="PAIA" loading="lazy" decoding="async"></div></div></section>'''
    return '<div class="flagship-home flagship-v2">'+lead+workbench+continuity+privacy+fair+close+'</div>'
